// Portable non-consuming smoke for accounts generated by scripts/CreateLocalUsers.java.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { chromium } = require('@playwright/test');
const base = process.env.SAFEBOX_BASE_URL || 'http://127.0.0.1:8080';
const password = process.env.SAFEBOX_LOCAL_PASSWORD;
assert(password && password.length >= 16, 'Set SAFEBOX_LOCAL_PASSWORD to the value used for local setup');
assert(['localhost', '127.0.0.1'].includes(new URL(base).hostname), 'Local smoke accepts loopback only');
const output = path.resolve(process.env.SAFEBOX_SMOKE_OUTPUT || 'test-results/clean-clone');
fs.mkdirSync(output, { recursive: true });
const results = { checks: [], errors: [] };
async function main() {
  const browser = await chromium.launch({ headless: true });
  try {
    for (const [role, pagePath] of [
      ['customer', '/stitch/kho_dang_thue_safebox_storage.html'],
      ['staff', '/staff-tasks.html'], ['manager', '/staff-tasks.html'],
      ['business', '/stitch/business-reports.html'], ['admin', '/management-admin.html']
    ]) {
      const context = await browser.newContext({ timezoneId: 'Asia/Ho_Chi_Minh' });
      const page = await context.newPage();
      page.on('pageerror', e => results.errors.push({ role, message: e.message }));
      const login = await context.request.post(base + '/api/auth/login', {
        data: { email: role + '@local.safebox.test', password }
      });
      assert.equal(login.status(), 200, role + ' login');
      const auth = await login.json();
      await context.addInitScript(auth => {
        sessionStorage.setItem('safebox.token', auth.token);
        sessionStorage.setItem('safebox.user', JSON.stringify(auth.user));
      }, auth);
      const apiFailures = [];
      page.on('response', r => { if (r.url().startsWith(base + '/api/') && r.status() >= 400) apiFailures.push({ url: new URL(r.url()).pathname, status: r.status() }); });
      const response = await page.goto(base + pagePath);
      assert.equal(response.status(), 200, role + ' page');
      await page.waitForFunction(() => document.body.style.visibility !== 'hidden');
      if (role === 'business') await page.locator('#results').waitFor({ state: 'visible' });
      else if (['staff', 'manager'].includes(role)) await page.waitForFunction(() => document.getElementById('task-loading').hidden);
      else await page.waitForLoadState('networkidle');
      assert.equal(new URL(page.url()).pathname, pagePath, role + ' authorized route');
      assert.deepEqual(apiFailures, [], role + ' API requests');
      await page.screenshot({ path: path.join(output, role + '.png'), fullPage: true });
      if (role === 'customer') {
        await page.goto(base + '/storage.html');
        await page.waitForLoadState('networkidle');
        assert.deepEqual(apiFailures, [], 'Fresh-schema public discovery');
        const denied = await context.request.get(base + '/api/reports/facilities', { headers: { Authorization: 'Bearer ' + auth.token } });
        assert.equal(denied.status(), 403, 'Customer cannot access manager reports');
      }
      results.checks.push({ role, pagePath, result: 'PASS' });
      console.log('PASS ' + role + ' login, authorized page and API loads');
      await context.close();
    }
    assert.deepEqual(results.errors, []);
  } finally {
    await browser.close();
    fs.writeFileSync(path.join(output, 'result.json'), JSON.stringify(results, null, 2));
  }
}
main().catch(e => { console.error(e.message); process.exitCode = 1; });
